// План specs/estimates-sms-link.md 1.2 (кейс ES-02). Гость (без входа), смета EST-0013 компании «test». Только чтение. @prod-safe
import * as fs from 'fs';
import { test, expect } from '@playwright/test';
import { EST_0013, openPublicEstimate } from './estimate-sms-helpers';

const DEVICES = ['@desktop', '@android'] as const;

test.describe('Estimate SMS link: public page (#05c270)', () => {
  for (const device of DEVICES) {
    test(`Public estimate page opens without login and Download PDF saves the file #05c270 ${device} @prod-safe`, async ({ page }) => {
      // Шаг 1: ссылка без входа
      await openPublicEstimate(page, EST_0013.token);

      // Шаг 2: содержимое (комментарий программиста п.1; скрин 05c270-4-public-page-desktop.png)
      await expect(page.getByText(EST_0013.company, { exact: true }).first()).toBeVisible();
      await expect(page.getByText(`Estimate #${EST_0013.number}`)).toBeVisible();
      await expect(page.getByText(EST_0013.title, { exact: true })).toBeVisible();
      await expect(page.getByText('Date', { exact: true })).toBeVisible();
      await expect(page.getByText('Items and services')).toBeVisible();
      await expect(page.getByText(EST_0013.item, { exact: true })).toBeVisible();
      await expect(page.getByText(EST_0013.itemLine)).toBeVisible();
      await expect(page.getByText('Estimated total')).toBeVisible();
      await expect(page.getByText(EST_0013.total).last()).toBeVisible();

      // Шаг 3: Download PDF скачивает Estimate-EST-0013.pdf
      const [download] = await Promise.all([
        page.waitForEvent('download', { timeout: 30_000 }),
        page.getByRole('button', { name: 'Download PDF' }).click(),
      ]);
      expect(download.suggestedFilename()).toBe(EST_0013.pdf);
      const file = await download.path();
      expect(fs.statSync(file).size, 'PDF не пустой').toBeGreaterThan(1000);
      expect(fs.readFileSync(file).subarray(0, 4).toString(), 'файл — PDF').toBe('%PDF');
    });
  }
});
